const finalSet = new Set(finalItems.map(idGetter));
const originalSet = new Set(originalItems.map(idGetter));
const originalMap = new Map(originalItems.map(i => [idGetter(i), i]));

// Inserts: Item exists in Final but not Original
const toInsert = finalItems.filter(item => !originalSet.has(idGetter(item)));

// Deletes: Item exists in Original but not Final
const toDelete = originalItems.filter(item => !finalSet.has(idGetter(item)));

// Updates: Item exists in Both, but values changed
const toUpdate = [];
finalItems.forEach(newItem => {
    const oldItem = originalMap.get(idGetter(newItem));
    if (oldItem) {
        const hasChanged =
            newItem.CustomEmployeeAmount != oldItem.CustomEmployeeAmount ||
            newItem.CustomEmployerAmount != oldItem.CustomEmployerAmount;

        if (hasChanged) {
            newItem._linkId = oldItem._linkId;
            toUpdate.push(newItem);
        }
    }
});

return { toInsert, toUpdate, toDelete }

const { toInsert, toUpdate, toDelete } = this._diffLists(originalItems, finalItems, getIdFn);

const insertPayload = toInsert.map(createInsertPayloadFn);
const updatePayload = toUpdate.map(item => ({
    Id: item._linkId,
    CustomEmployeeAmount: item.CustomEmployeeAmount || null,
    CustomEmployerAmount: item.CustomEmployerAmount || null
}));
const deletePayload = toDelete.map(item => ({ Id: item._linkId }));

const promises = [];
if (insertPayload.length > 0) promises.push(this._batchInsert(apiService, endpoint, insertPayload));
if (updatePayload.length > 0) promises.push(this._batchUpdate(apiService, endpoint, updatePayload));
if (deletePayload.length > 0) promises.push(this._batchDelete(apiService, endpoint, deletePayload));

await Promise.all(promises);

if (!componentId) throw new Error("Component ID is missing");

const config = this._config[targetType];
if (!config) throw new Error(`Configuration for ${targetType} not found`);

const componentForeignKey = componentType === 'earning' ? 'EarningId' : 'BenefitId';
const compClass = componentType.toUpperCase();

const getId = (item) => item.Id;

const mapInsert = (item) => ({
    [componentForeignKey]: componentId,
    [config.foreignKey]: item.Id,
    ComponentClass: compClass,
    CustomEmployeeAmount: item.CustomEmployeeAmount || null,
    CustomEmployerAmount: item.CustomEmployerAmount || null
});

return this._executeComponentSync(
    apiService,
    config.endpoint,
    originalItems,
    finalItems,
    getId,
    mapInsert
);

if (!targetId) throw new Error(`${targetType} ID is missing`);

const config = this._config[targetType];
if (!config) throw new Error(`Configuration for ${targetType} not found`);

const getId = (item) => componentType === 'EARNING' ? item.EarningId : item.BenefitId;

const mapInsert = (item) => ({
    [config.foreignKey]: targetId,
    ComponentClass: componentType,
    ...(componentType === 'EARNING' ? { EarningId: item.EarningId } : { BenefitId: item.BenefitId }),
    CustomEmployeeAmount: item.CustomEmployeeAmount || null,
    CustomEmployerAmount: item.CustomEmployerAmount || null
});

return this._executeComponentSync(
    apiService,
    config.endpoint,
    originalItems,
    finalItems,
    getId,
    mapInsert
);
